package com.dlt.predictor.lottery;import org.springframework.stereotype.Service;import java.time.LocalDate;import java.util.*;import java.util.concurrent.*;
@Service public class DrawStore{private final Map<String,Draw>draws=new ConcurrentHashMap<>();private long id=1;public DrawStore(){upsert("2025001",LocalDate.now().minusDays(20),List.of(1,6,12,20,35),List.of(3,11));upsert("2025002",LocalDate.now().minusDays(15),List.of(2,7,14,21,32),List.of(1,9));upsert("2025003",LocalDate.now().minusDays(10),List.of(4,8,18,22,30),List.of(5,12));}public synchronized Draw upsert(String issue,LocalDate date,List<Integer>f,List<Integer>b){var old=draws.get(issue);var d=new Draw(old==null?id++:old.id(),issue,date,DltNumbers.of(f,b),"manual");draws.put(issue,d);return d;}public List<Draw>all(){return draws.values().stream().sorted(Comparator.comparing(Draw::drawDate).reversed()).toList();}public Optional<Draw>find(String issue){return Optional.ofNullable(draws.get(issue));}}
